pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ACCURAL_DEPOSIT c;

    function setUp() public {
        c = new ACCURAL_DEPOSIT();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount > 0 && address(this).balance >= amount);
        uint256 b0;
        try c.balances(address(this)) returns (uint256 __r) { b0 = __r; } catch { return; }
        uint c0 = address(c).balance;
        bool reverted;
        try c.Deposit{value: amount}() { reverted = false; }
        catch { reverted = true; }
        uint256 b1;
        try c.balances(address(this)) returns (uint256 __r) { b1 = __r; } catch { return; }
        uint c1 = address(c).balance;
        assertTrue((!reverted && b1 == b0 + amount && c1 == c0 + amount) ||
               (reverted && b1 == b0 && c1 == c0));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
